start=s.index('class SimplePie_Credit')
s=s[:start]+'''class SimplePie_Credit implements \\Stringable
{
	/**
	 * Constructor, used to input the data
	 *
	 * For documentation on all the parameters, see the corresponding
	 * properties and their accessors
	 *
	 * @param string|null $role Credited role (see get_role())
	 * @param string|null $scheme Organizational scheme (see get_scheme())
	 * @param string|null $name Credited name (see get_name())
	 */
	public function __construct(
		public $role = null,
		public $scheme = null,
		public $name = null
	)
	{
	}

	/**
	 * String-ified version
	 *
	 * @return string
	 */
	public function __toString(): string
	{
		// There is no $this->data here
		return md5(serialize($this));
	}

	/**
	 * Get the role of the person receiving credit
	 *
	 * @return string|null
	 */
	public function get_role()
	{
		return $this->role;
	}

	/**
	 * Get the organizational scheme
	 *
	 * @return string|null
	 */
	public function get_scheme()
	{
		return $this->scheme;
	}

	/**
	 * Get the credited person/entity's name
	 *
	 * @return string|null
	 */
	public function get_name()
	{
		return $this->name;
	}
}
'''
